package com.ruoyi.paicli.service;

import com.ruoyi.paicli.domain.*;
import com.ruoyi.paicli.configuration.PcProperties;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.scheduling.annotation.Scheduled;
import java.util.*;

/** 领取和lease/fencing仲裁只在MySQL内进行，不启动Runner或shell。 */
public class PcRunnerService {
    private final PcStore store;private final PcAccess access;private final PcIdempotency idem;private final PcEvidence evidence;private final PcProperties properties;private final PcArtifactService artifacts;
    public PcRunnerService(PcStore s,PcAccess a,PcIdempotency i,PcEvidence e,PcProperties p,PcArtifactService ar){store=s;access=a;idem=i;evidence=e;properties=p;artifacts=ar;}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> claim(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":claim",key,input,()->{
        PcRecord workspace=access.workspace(actor.workspaceId(),actor.ownerId(),true);PcRecord runner=store.require(PcTable.RUNNER,actor.runnerId(),true);if(runner.getState().equals("REVOKED"))throw PcException.deny("Runner已撤销");
        if(store.mapper.activeTasks(actor.workspaceId(),null,null,null)>0)return Map.of("available",false,"reason","工作区已有执行任务或未知副作用待核对");
        for(PcRecord candidate:store.mapper.queued(actor.workspaceId(),actor.runnerId())){
            if(input.containsKey("taskId")&&candidate.getId()!=PcJson.number(input,"taskId"))continue;
            PcRecord task=store.require(PcTable.TASK,candidate.getId(),true);if(!"ENQUEUED".equals(task.getState()))continue;
            access.role(actor.workspaceId(),task.getOwnerId());if(store.mapper.activeTasks(null,task.getSessionId(),null,null)>0)continue;
            Map<String,Object> p=store.data(task);if(PcJson.number(p,"policyVersion")!=PcJson.number(store.data(workspace),"policyVersion")){task.setState("FAILED");p.put("failureReason","工作区策略已改变，请重新提交当前版本任务");store.save(PcTable.TASK,task,p);continue;}
            if(!Objects.equals(PcJson.text(p,"rootFingerprint"),PcJson.text(store.data(runner),"rootFingerprint")))throw PcException.deny("执行目录与任务快照不匹配");
            PcRecord old=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);long fence=old==null?1:old.getFencingToken()+1;
            PcRecord lease;if(old==null)lease=store.insert(PcTable.TASK_LEASE,actor.workspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),actor.runnerId(),"LEASE","ACTIVE","task:"+task.getId(),Map.of("taskId",String.valueOf(task.getId())));else lease=old;
            lease.setRunnerId(actor.runnerId());lease.setFencingToken(fence);lease.setState("ACTIVE");lease.setExpiresAt(store.clock.instant().plusSeconds(properties.getLeaseSeconds()));store.save(PcTable.TASK_LEASE,lease,store.data(lease));
            task.setState("RUNNING");task.setRunnerId(actor.runnerId());task.setFencingToken(fence);p.put("startedAt",store.clock.instant().toString());store.save(PcTable.TASK,task,p);
            PcRecord outbox=store.mapper.findKey(PcTable.DISPATCH_OUTBOX,"task:"+task.getId(),true);if(outbox==null)throw new IllegalStateException("任务缺少派发outbox");outbox.setState("DELIVERED");store.save(PcTable.DISPATCH_OUTBOX,outbox,Map.of("taskId",String.valueOf(task.getId()),"leaseId",String.valueOf(lease.getId()),"fencingToken",fence,"attempts",PcJson.number(store.data(outbox),"attempts")+1));
            evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"TASK_RUNNING",Map.of("taskId",String.valueOf(task.getId()),"version",task.getVersion()));
            evidence.audit(task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),"TASK_CLAIM","LEASED",Map.of("runnerId",actor.runnerId(),"fencingToken",fence));
            Map<String,Object> response=new LinkedHashMap<>();response.put("available",true);response.put("taskId",String.valueOf(task.getId()));response.put("turnId",String.valueOf(task.getParentId()));response.put("sessionId",String.valueOf(task.getSessionId()));response.put("workspaceId",String.valueOf(task.getWorkspaceId()));response.put("runnerId",String.valueOf(task.getRunnerId()));response.put("ownerId",String.valueOf(task.getOwnerId()));response.put("leaseId",String.valueOf(lease.getId()));response.put("fencingToken",fence);response.put("version",task.getVersion());response.put("policyVersion",p.get("policyVersion"));response.put("rootFingerprint",p.get("rootFingerprint"));response.put("expiresAt",lease.getExpiresAt().toString());response.put("payload",p);return response;
        }return Map.of("available",false);
    });}
    /** locked=true使执行点/回执与取消、撤销串行仲裁。allowCancel只用于心跳和实际结果上送。 */
    public PcRecord receiptTask(PcRunnerPrincipal actor,Map<String,Object> input){PcRecord task=store.require(PcTable.TASK,PcJson.number(input,"taskId"),true);if(!Objects.equals(task.getWorkspaceId(),actor.workspaceId())||!Objects.equals(task.getRunnerId(),actor.runnerId()))throw PcException.deny("迟到回执不属于本设备工作区");access.workspace(actor.workspaceId(),task.getOwnerId(),false);PcRecord device=store.require(PcTable.RUNNER,actor.runnerId(),true);long admin=store.data(device).get("administrationVersion") instanceof Number n?n.longValue():1;if(device.getState().equals("REVOKED")||admin!=actor.runnerVersion())throw PcException.deny("设备身份已撤销");return task;}
    public boolean lateReceipt(PcRecord task,Map<String,Object> input){PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);return lease==null||lease.getId()!=PcJson.number(input,"leaseId")||lease.getFencingToken()!=PcJson.number(input,"fencingToken")||!lease.getState().equals("ACTIVE")||!lease.getExpiresAt().isAfter(store.clock.instant())||PcSessionService.terminal(task.getState())||task.getState().equals("RECONCILE_REQUIRED");}
    public PcRecord lease(PcRunnerPrincipal actor,Map<String,Object> input,boolean allowCancel){
        long id=PcJson.number(input,"taskId");PcRecord task=store.require(PcTable.TASK,id,true);if(!Objects.equals(task.getWorkspaceId(),actor.workspaceId())||!Objects.equals(task.getRunnerId(),actor.runnerId()))throw PcException.deny("任务不属于本设备工作区");
        access.workspace(actor.workspaceId(),task.getOwnerId(),false);PcRecord runner=store.require(PcTable.RUNNER,actor.runnerId(),true);long admin=store.data(runner).get("administrationVersion") instanceof Number n?n.longValue():1;
        if(runner.getState().equals("REVOKED")||admin!=actor.runnerVersion())throw PcException.deny("设备授权已撤销");
        PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+id,true);
        if(lease==null||lease.getId()!=PcJson.number(input,"leaseId")||lease.getFencingToken()!=PcJson.number(input,"fencingToken")||!Objects.equals(lease.getRunnerId(),actor.runnerId())||!lease.getState().equals("ACTIVE")||!lease.getExpiresAt().isAfter(store.clock.instant()))throw new PcException(409,"PC_LEASE_FENCED","租约已失效或被新尝试替代，停止新副作用并核对已有结果");
        Map<String,Object> taskData=store.data(task);if(!allowCancel&&taskData.get("wechatBindingId")!=null){PcRecord binding=store.require(PcTable.WECHAT_BINDING,PcJson.number(taskData,"wechatBindingId"),true);Map<String,Object> bd=store.data(binding);long definition=bd.get("channelVersion") instanceof Number n?n.longValue():bd.get("configurationVersion") instanceof Number n?n.longValue():binding.getVersion();if(!Objects.equals(binding.getWorkspaceId(),task.getWorkspaceId())||PcJson.number(bd,"boundUserId")!=task.getOwnerId()||definition!=PcJson.number(taskData,"wechatConfigVersion")||!Set.of("BOUND","RUNNING").contains(binding.getState()))throw PcException.deny("微信绑定或策略已撤销，不能继续当前任务");}if(!allowCancel){store.version(task,PcJson.number(input,"version"));if(!Set.of("RUNNING","WAITING_APPROVAL").contains(task.getState()))throw PcException.conflict("当前任务状态不允许新工具执行");}
        return task;
    }
    @Transactional("paicliTransactionManager")
    public Map<String,Object> heartbeat(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":heartbeat",key,input,()->{
        PcRecord task=lease(actor,input,true);PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);lease.setExpiresAt(store.clock.instant().plusSeconds(properties.getLeaseSeconds()));store.save(PcTable.TASK_LEASE,lease,store.data(lease));
        PcRecord runner=store.require(PcTable.RUNNER,actor.runnerId(),true);Map<String,Object> p=store.data(runner);p.put("lastHeartbeatAt",store.clock.instant().toString());store.save(PcTable.RUNNER,runner,p);
        return Map.of("version",task.getVersion(),"expiresAt",lease.getExpiresAt().toString(),"cancelRequested",task.getState().equals("CANCELLING"));
    });}
    @Transactional("paicliTransactionManager")
    public Map<String,Object> event(PcRunnerPrincipal actor,String key,Map<String,Object> input){return idem.run("runner:"+actor.runnerId()+":events",key,input,()->{
        PcRecord task=lease(actor,input,true);String eventId=PcJson.text(input,"eventId"),type=PcJson.text(input,"type");if(!eventId.matches("[A-Za-z0-9._:-]{1,128}"))throw PcException.invalid("事件ID非法");Map<String,Object> payload=PcJson.object(input,"payload");String dedup="runner:"+actor.runnerId()+":"+eventId;String requestHash=store.json.hash(Map.of("type",type,"payload",payload));
        PcRecord existing=store.mapper.findKey(PcTable.EVENT,dedup,false);if(existing!=null){if(!requestHash.equals(store.data(existing).getOrDefault("requestHash",existing.getContentHash())))throw new PcException(409,"PC_EVENT_ID_REUSED","同一事件ID包含不同内容");return evidence.eventView(existing);}
        if(payload.get("eventArtifactId")!=null){Map<String,Object> metadata=artifacts.runnerOutputMetadata(PcJson.number(payload,"eventArtifactId"),task.getWorkspaceId(),task.getOwnerId(),task.getSessionId());if(!Objects.toString(metadata.get("parentId"),"").equals(String.valueOf(task.getId()))||!Objects.equals(metadata.get("sha256"),payload.get("eventArtifactSha256"))||PcJson.number(metadata,"size")!=PcJson.number(payload,"eventArtifactSize"))throw PcException.deny("事件原始产物引用不属于当前任务或哈希/长度不匹配");payload=new LinkedHashMap<>(payload);payload.put("eventArtifactContentUrl","/paicli/v1/artifacts/"+metadata.get("id")+"/content");}
        if(!Set.of("MESSAGE","LEDGER_MESSAGE","MODEL_DELTA","USAGE","DIAGNOSTICS","PLAN_CREATED","PLAN_STEP","PLAN_PROGRESS","TEAM_PROGRESS","CONTEXT_SUMMARY","CONTEXT_COMPACT","PROJECT_MEMORY","DIRECTORY_RESULT","INDEX_MANIFEST","SEARCH_RESULT","GRAPH_RESULT","SNAPSHOT","ARTIFACT","CONNECTION_RESULT","HARNESS_RESULT","TASK_COMPLETED","TASK_FAILED","TASK_CANCELLED").contains(type))throw PcException.invalid("未注册的事件类型");
        if(type.equals("LEDGER_MESSAGE")){
            Map<String,Object> ledger=new LinkedHashMap<>(payload);ledger.remove("message");ledger.put("taskId",String.valueOf(task.getId()));Map<String,Object> stored;
            if(payload.get("message")==null){if(PcJson.text(payload,"event").isBlank())throw PcException.invalid("原始账本事件须有event");stored=new LinkedHashMap<>();stored.put("_ledger",artifacts.storeLedgerImages(ledger,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getId()));}
            else{Map<String,Object> message=PcJson.object(payload,"message");if(!Set.of("assistant","tool","system").contains(PcJson.text(message,"role")))throw PcException.invalid("Runner账本不得伪造用户消息");stored=new LinkedHashMap<>(artifacts.storeLedgerImages(message,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getId()));stored.put("_ledger",ledger);}
            PcRecord row=store.insert(PcTable.MESSAGE,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getSessionId(),actor.runnerId(),payload.get("message")==null?"LEDGER_EVENT":"MESSAGE","APPENDED",dedup,stored);row.setSequenceNumber(store.require(PcTable.SESSION,task.getSessionId(),false).getSequenceNumber()+1);store.save(PcTable.MESSAGE,row,stored);payload=new LinkedHashMap<>(payload);if(payload.get("message")!=null)payload.put("message",stored);else payload=artifacts.storeLedgerImages(payload,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getId());
        }
        if(type.equals("MESSAGE")){String role=PcJson.text(payload,"role");if(!Set.of("assistant","tool","system").contains(role))throw PcException.invalid("Runner不能伪造用户消息");PcRecord message=store.insert(PcTable.MESSAGE,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getSessionId(),actor.runnerId(),"MESSAGE","APPENDED",dedup,payload);message.setSequenceNumber(store.require(PcTable.SESSION,task.getSessionId(),false).getSequenceNumber()+1);store.save(PcTable.MESSAGE,message,payload);}
        if(type.equals("PROJECT_MEMORY"))projectMemory(task,payload);if(type.equals("DIRECTORY_RESULT")){requireControlResult(task,"REPOSITORY_LIST");Map<String,Object> args=PcJson.object(store.data(task),"arguments");if(!Objects.equals(args.get("path"),payload.get("path"))||!"RUNNER".equals(payload.get("source"))||!(payload.get("entries") instanceof List<?> entries)||entries.size()>10000)throw PcException.invalid("目录结果必须对应冻结路径及实际entries");for(Object item:entries)if(!(item instanceof Map<?,?> entry)||entry.get("name")==null||entry.get("name").toString().isBlank()||entry.get("name").toString().length()>4096||entry.get("name").toString().matches(".*[\\\\/].*")||!Set.of("FILE","DIRECTORY","LINK","OTHER").contains(entry.get("type")))throw PcException.invalid("目录项元数据非法");}
        if(type.equals("USAGE"))usage(task,payload);
        if(type.equals("CONTEXT_COMPACT"))compact(task,payload);
        if(type.equals("PLAN_CREATED"))payload=plan(task,payload);
        if(type.equals("PLAN_STEP"))planStep(task,payload);
        if(type.equals("CONTEXT_SUMMARY"))summary(task,payload);
        if(type.equals("INDEX_MANIFEST")){requireControlResult(task,"INDEX_BUILD");metadata(PcTable.INDEX_MANIFEST,task,payload,"INDEX");}
        if(Set.of("SEARCH_RESULT","GRAPH_RESULT").contains(type)){requireControlResult(task,type.equals("SEARCH_RESULT")?"REPOSITORY_SEARCH":"AST_GRAPH");Map<String,Object> combined=new LinkedHashMap<>(PcJson.object(store.data(task),"arguments"));combined.putAll(payload);payload=combined;}
        if(type.equals("SEARCH_RESULT"))store.insert(PcTable.INDEX_MANIFEST,task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),actor.runnerId(),"SEARCH_RESULT","READY",null,payload);
        if(type.equals("GRAPH_RESULT"))store.insert(PcTable.INDEX_MANIFEST,task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),actor.runnerId(),"GRAPH_RESULT","READY",null,payload);
        if(type.equals("HARNESS_RESULT")){requireControlResult(task,"HARNESS_QUICK","HARNESS_NORMAL","HARNESS_INLINE");if(!Objects.toString(PcJson.object(store.data(task),"arguments").get("harnessId"),"").equals(Objects.toString(payload.get("harnessId"),"")))throw PcException.deny("Harness对象不等于冻结指令");PcRecord h=store.require(PcTable.HARNESS_RUN,PcJson.number(payload,"harnessId"),true);if(!Objects.equals(h.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(h.getOwnerId(),task.getOwnerId()))throw PcException.deny("Harness结果归属非法");Map<String,Object> hd=store.data(h);hd.putAll(payload);h.setState("COMPLETED");store.save(PcTable.HARNESS_RUN,h,hd);}
        if(type.equals("SNAPSHOT"))snapshotResult(task,payload);
        if(type.equals("ARTIFACT"))metadata(PcTable.ARTIFACT,task,payload,"ARTIFACT");
        if(type.equals("CONNECTION_RESULT")){requireControlResult(task,PcJson.text(store.data(task),"operation"));connectionResult(task,payload);}
        if(type.startsWith("TASK_"))finish(task,type,payload);
        outputBudget(task,payload,type.startsWith("TASK_"));
        Map<String,Object> result=evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),dedup,type,payload);PcRecord saved=store.mapper.findKey(PcTable.EVENT,dedup,true);Map<String,Object> savedData=store.data(saved);savedData.put("requestHash",requestHash);store.save(PcTable.EVENT,saved,savedData);Map<String,Object> response=new LinkedHashMap<>(result);response.put("version",task.getVersion());return response;
    });}
    private void projectMemory(PcRecord task,Map<String,Object> payload){Map<String,Object> taskData=store.data(task);if(!"INIT_PROJECT_MEMORY".equals(taskData.get("operation")))throw PcException.deny("项目规则只能由初始化控制指令写入");Map<String,Object> args=PcJson.object(taskData,"arguments");if(!Objects.equals(Boolean.TRUE.equals(args.get("force")),Boolean.TRUE.equals(payload.get("force"))))throw PcException.conflict("项目规则force与冻结指令不一致");if(store.mapper.list(PcTable.TOOL_CALL,task.getWorkspaceId(),task.getOwnerId(),task.getId(),"CONSUMED").stream().noneMatch(c->c.getKind().equals("control__INIT_PROJECT_MEMORY")))throw PcException.deny("项目初始化没有已消费的许可");PcProjectRuleService.validateInit(store,task.getWorkspaceId(),args);String content=PcJson.text(payload,"content");if(content.isBlank()||content.getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw PcException.invalid("项目规则内容为空或超过64KB");if(PcSecretPolicy.contains(content))throw PcException.invalid("项目规则不能携带明文凭证");for(PcRecord old:PcProjectRuleService.rootRules(store,task.getWorkspaceId())){Map<String,Object> previous=store.data(old);store.insert(PcTable.MEMORY_VERSION,old.getWorkspaceId(),old.getOwnerId(),old.getId(),old.getSessionId(),old.getRunnerId(),"ROOT_PAI_BEFORE_INIT","APPENDED",null,previous);old.setState("REPLACED");store.save(PcTable.MEMORY,old,previous);}Map<String,Object> data=new LinkedHashMap<>(Map.of("content",content,"fact",content,"scope","PROJECT","source","PROJECT_MEMORY","layer","ROOT_PAI","sourcePath","PAI.md","sha256",PcJson.digest(content),"registeredLayer",true,"enabled",true,"verifiedAt",store.clock.instant().toString()));data.put("originalContent",content);data.put("encoding","UTF-8");PcRecord row=store.insert(PcTable.MEMORY,task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),task.getRunnerId(),"PROJECT_RULE","VERIFIED",null,data);store.insert(PcTable.MEMORY_VERSION,task.getWorkspaceId(),task.getOwnerId(),row.getId(),task.getSessionId(),task.getRunnerId(),"VERSION","APPENDED",null,data);evidence.audit(task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),"PROJECT_MEMORY","STORED",Map.of("memoryId",row.getId(),"contentHash",row.getContentHash(),"location","CENTER_ROOT_PAI","replacedVersions",args.get("rootRuleVersions")));}
    public void outputBudget(PcRecord task,Object payload,boolean terminal){PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);Map<String,Object> p=store.data(lease);long used=p.get("outputBytes") instanceof Number n?n.longValue():0;long bytes=store.json.write(payload).getBytes(java.nio.charset.StandardCharsets.UTF_8).length;if(!terminal&&used+bytes>20L*1024*1024)throw new PcException(413,"PC_TASK_OUTPUT_LIMIT","单任务累计输出和事件超过20MB，请使用产物引用");p.put("outputBytes",used+bytes);store.save(PcTable.TASK_LEASE,lease,p);}
    private void usage(PcRecord task,Map<String,Object> payload){PcRecord session=store.require(PcTable.SESSION,task.getSessionId(),true);Map<String,Object> sd=store.data(session),usage=new LinkedHashMap<>(payload);boolean present=Boolean.TRUE.equals(payload.get("usagePresent"));long input=token(payload,"inputTokens"),output=token(payload,"outputTokens"),cached=token(payload,"cachedInputTokens"),total=token(payload,"totalTokens"),charge=total;if(present){if(total<input+output||cached>input)throw PcException.invalid("供应商Token计量字段不一致");usage.put("source","PROVIDER");}else{Map<String,Object> policy=store.data(store.mapper.findKey(PcTable.POLICY_VERSION,"workspace:"+task.getWorkspaceId(),false));long reserved=token(payload,"reserved"),minimum=Math.min(PcJson.number(policy,"taskTokenBudget"),policy.get("maxOutputTokens") instanceof Number n?n.longValue():4096);charge=Math.max(reserved,minimum);usage.put("chargedTokens",charge);usage.put("reserved",charge);usage.put("source","ESTIMATE");usage.put("status","UNKNOWN");usage.put("usagePresent",false);sd.put("usageIncomplete",true);}
        PcRecord lease=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);Map<String,Object> ld=store.data(lease);long used=ld.get("usedTokens") instanceof Number n?n.longValue():0;ld.put("usedTokens",Math.addExact(used,charge));store.save(PcTable.TASK_LEASE,lease,ld);PcRecord workspace=store.require(PcTable.WORKSPACE,task.getWorkspaceId(),true);Map<String,Object> wd=store.data(workspace);String day=store.clock.instant().atZone(java.time.ZoneOffset.UTC).toLocalDate().toString();long daily=day.equals(wd.get("usageDay"))&&wd.get("dailyTokenUsed") instanceof Number n?n.longValue():0;wd.put("usageDay",day);wd.put("dailyTokenUsed",Math.addExact(daily,charge));store.save(PcTable.WORKSPACE,workspace,wd);sd.put("usage",usage);if(present)sd.put("estimatedTokens",input+output);store.save(PcTable.SESSION,session,sd);Object bindingId=store.data(task).get("wechatBindingId");if(bindingId!=null){PcRecord binding=store.require(PcTable.WECHAT_BINDING,Long.parseLong(bindingId.toString()),true);Map<String,Object> bd=store.data(binding);long previous=day.equals(bd.get("budgetDay"))&&bd.get("dailyUsed") instanceof Number n?n.longValue():0;bd.put("budgetDay",day);bd.put("dailyUsed",Math.addExact(previous,charge));store.save(PcTable.WECHAT_BINDING,binding,bd);}}
    private long token(Map<String,Object> payload,String field){long n=payload.containsKey(field)?PcJson.number(payload,field):0;if(n<0||n>100000000)throw PcException.invalid("Token计量非法："+field);return n;}
    private void compact(PcRecord task,Map<String,Object> payload){
        if(!Boolean.TRUE.equals(payload.get("derived"))||!(payload.get("messages") instanceof List<?> messages)||messages.isEmpty())throw PcException.invalid("派生摘要消息缺失");for(Object value:messages){if(!(value instanceof Map<?,?> m)||!Set.of("user","assistant","tool","system").contains(Objects.toString(m.get("role"),"")))throw PcException.invalid("摘要消息角色非法");}
        PcRecord session=store.require(PcTable.SESSION,task.getSessionId(),true);Map<String,Object> data=new LinkedHashMap<>(payload);
        if("AUTOCOMPACTION".equals(payload.get("source"))){long sourceSequence=PcJson.number(payload,"compactionLedgerSequence");PcRecord source=store.mapper.list(PcTable.MESSAGE,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),null).stream().filter(r->r.getKind().equals("LEDGER_EVENT")).filter(r->{Map<String,Object> entry=PcJson.object(store.data(r),"_ledger");return "compaction".equals(entry.get("event"))&&Objects.toString(entry.get("taskId"),"").equals(String.valueOf(task.getId()))&&entry.get("sequence") instanceof Number n&&n.longValue()==sourceSequence;}).findFirst().orElseThrow(()->PcException.deny("自动压缩缺少同任务正式原始账本来源"));Map<String,Object> metadata=PcJson.object(PcJson.object(store.data(source),"_ledger"),"metadata");if(!store.json.hash(metadata.get("derivedMessages")).equals(store.json.hash(messages)))throw PcException.conflict("自动压缩视图与原账本来源不一致");long before=PcJson.number(metadata,"beforeTokens"),after=PcJson.number(metadata,"afterTokens");if(after<0||after>=before)throw PcException.invalid("自动压缩未降低Token");data.put("startSequence",store.data(session).getOrDefault("contextStartSequence",0));data.put("endSequence",source.getSequenceNumber());data.put("sourceLedgerId",String.valueOf(source.getId()));data.put("tokensBefore",before);data.put("tokensAfter",after);
        }else{if(!"CONTEXT_COMPRESS".equals(store.data(task).get("operation")))throw PcException.deny("手工摘要必须来自固定压缩控制任务");requireControlResult(task,"CONTEXT_COMPRESS");Map<String,Object> args=PcJson.object(store.data(task),"arguments");if(PcJson.number(payload,"sessionVersion")!=PcJson.number(args,"sessionVersion"))throw PcException.conflict("压缩原版本非法");data.put("endSequence",args.getOrDefault("ledgerEndSequence",session.getSequenceNumber()));data.put("startSequence",args.getOrDefault("contextStartSequence",0));}
        boolean actorView="AUTOCOMPACTION".equals(payload.get("source"))&&!"react".equalsIgnoreCase(PcJson.text(payload,"viewMode"));data=artifacts.storeLedgerImages(data,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getId());store.insert(PcTable.CONTEXT_SUMMARY,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getSessionId(),task.getRunnerId(),actorView?"ACTOR_SUMMARY":"SUMMARY","VERIFIED",null,data);if(actorView)return;Map<String,Object> sd=store.data(session);sd.put("compressionCount",(sd.get("compressionCount") instanceof Number n?n.longValue():0)+1);sd.put("lastCompressionStatus","COMPLETED");if(data.get("tokensAfter")!=null)sd.put("estimatedTokens",data.get("tokensAfter"));store.save(PcTable.SESSION,session,sd);
    }
    private void finish(PcRecord task,String type,Map<String,Object> payload){
        String state=type.substring(5);if(PcSessionService.terminal(task.getState()))throw PcException.conflict("终态任务不能被迟到事件复活");
        var calls=store.mapper.list(PcTable.TOOL_CALL,task.getWorkspaceId(),null,task.getId(),null);if(state.equals("COMPLETED")&&calls.stream().anyMatch(r->Set.of("PENDING","PERMITTED","CONSUMED").contains(r.getState())))throw PcException.conflict("仍有待批准或未确认回执的工具，不能完成任务");
        if(task.getState().equals("CANCELLING")&&!state.equals("CANCELLED"))throw PcException.conflict("取消请求须由取消回执确认，不能报告正常完成");
        if(state.equals("COMPLETED")){var plans=store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),null,task.getId(),null);for(PcRecord plan:plans){for(Map<String,Object> step:steps(store.data(plan))){if(!Set.of("COMPLETED","SKIPPED","CANCELLED").contains(PcJson.text(step,"status"))||PcJson.text(step,"reviewStatus").equals("FAILED"))throw PcException.conflict("计划仍有未完成或审查失败步骤，不能报告成功");}}
            if(PcJson.text(store.data(task),"mode").equals("TEAM")&&!"PASSED".equals(payload.get("reviewStatus")))throw PcException.conflict("团队审查未通过不能标记完成");}
        task.setState(state);Map<String,Object> p=store.data(task);p.putAll(payload);p.put("finishedAt",store.clock.instant().toString());if(p.get("startedAt") instanceof String started){try{p.put("durationMs",Math.max(0,java.time.Duration.between(java.time.Instant.parse(started),store.clock.instant()).toMillis()));}catch(java.time.format.DateTimeParseException ignored){throw PcException.invalid("任务开始时间记录非法");}}store.save(PcTable.TASK,task,p);for(PcRecord plan:store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),null)){Map<String,Object> data=store.data(plan);data.put("finishedAt",p.get("finishedAt"));plan.setState(state);store.save(PcTable.PLAN,plan,data);}PcRecord l=store.mapper.findKey(PcTable.TASK_LEASE,"task:"+task.getId(),true);l.setState("RELEASED");store.save(PcTable.TASK_LEASE,l,store.data(l));
        if(task.getParentId()!=null){PcRecord turn=store.require(PcTable.TURN,task.getParentId(),true);turn.setState(state);store.save(PcTable.TURN,turn,store.data(turn));}
        evidence.audit(task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),"TASK_TERMINAL",state,Map.of("fencingToken",task.getFencingToken()));
    }
    public Map<String,Object> plan(PcRecord task,Map<String,Object> payload){
        List<Map<String,Object>> steps=steps(payload);validateDag(steps);var previous=store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),null);int replan=payload.get("replanCount") instanceof Number n?n.intValue():0;
        if(replan<0||replan>2)throw PcException.invalid("重规划次数超过2次上限");
        Map<String,Object> p=new LinkedHashMap<>(payload);p.put("steps",steps);p.put("mode",store.data(task).get("mode"));p.put("valid",true);p.put("validationErrors",List.of());p.put("replanCount",replan);p.put("maxReplans",2);p.put("approvedVersion",0L);p.put("definitionVersion",previous.isEmpty()?1:((Number)store.data(previous.get(0)).getOrDefault("definitionVersion",1)).longValue()+1);
        PcRecord plan;if(previous.isEmpty())plan=store.insert(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),task.getRunnerId(),"PLAN","DRAFT",null,p);else{plan=store.require(PcTable.PLAN,previous.get(0).getId(),true);plan.setState("DRAFT");store.save(PcTable.PLAN,plan,p);}
        for(PcRecord old:store.mapper.list(PcTable.PLAN_STEP,task.getWorkspaceId(),null,plan.getId(),null)){old.setState("SUPERSEDED");store.save(PcTable.PLAN_STEP,old,store.data(old));}for(Map<String,Object> step:steps){Map<String,Object> data=new LinkedHashMap<>(step);data.put("planDefinitionVersion",p.get("definitionVersion"));store.insert(PcTable.PLAN_STEP,task.getWorkspaceId(),task.getOwnerId(),plan.getId(),task.getSessionId(),task.getRunnerId(),"STEP","PENDING","plan:"+plan.getId()+":v"+p.get("definitionVersion")+":"+PcJson.text(step,"id"),data);}
        invalidateApprovals(task);Map<String,Object> view=new LinkedHashMap<>(p);view.put("planId",String.valueOf(plan.getId()));view.put("planVersion",p.get("definitionVersion"));view.put("version",plan.getVersion());return view; // 修改内容使旧permit/批准全部失效。
    }
    public Map<String,Object> reviewedPlan(PcRecord task,Map<String,Object> input){Map<String,Object> created=plan(task,input);evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"PLAN_CREATED",created);return created;}
    private void planStep(PcRecord task,Map<String,Object> payload){
        var plans=store.mapper.list(PcTable.PLAN,task.getWorkspaceId(),task.getOwnerId(),task.getId(),null);if(plans.isEmpty())throw PcException.invalid("任务没有计划");PcRecord p=store.require(PcTable.PLAN,plans.get(0).getId(),true);Map<String,Object> data=store.data(p);List<Map<String,Object>> steps=steps(data);String target=PcJson.text(payload,"id"),state=PcJson.text(payload,"status");
        if(!Set.of("RUNNING","COMPLETED","FAILED","CANCELLED","SKIPPED").contains(state))throw PcException.invalid("步骤状态非法");Map<String,Object> step=steps.stream().filter(s->target.equals(PcJson.text(s,"id"))).findFirst().orElseThrow(()->PcException.invalid("步骤ID不存在"));
        if(Set.of("RUNNING","COMPLETED").contains(state)&&(!"APPROVED".equals(p.getState())||PcJson.number(data,"approvedVersion")!=PcJson.number(data,"definitionVersion")))throw PcException.conflict("计划当前定义未经批准，不能推进执行步骤");
        if(Set.of("RUNNING","COMPLETED").contains(state))for(Object d:(List<?>)step.getOrDefault("dependencies",List.of())){var dep=steps.stream().filter(s->String.valueOf(d).equals(PcJson.text(s,"id"))).findFirst().orElseThrow();if(!"COMPLETED".equals(PcJson.text(dep,"status")))throw PcException.conflict("依赖步骤尚未完成");}
        if(state.equals("COMPLETED")&&"FAILED".equals(PcJson.text(payload,"reviewStatus")))state="FAILED";
        step.putAll(payload);step.put("status",state);data.put("steps",steps);store.save(PcTable.PLAN,p,data);PcRecord row=store.mapper.findKey(PcTable.PLAN_STEP,"plan:"+p.getId()+":v"+data.get("definitionVersion")+":"+target,true);if(row==null)throw PcException.conflict("计划步骤正式记录缺失");Map<String,Object> recorded=store.data(row);recorded.putAll(step);row.setState(state);store.save(PcTable.PLAN_STEP,row,recorded);
    }
    private void requireControlResult(PcRecord task,String... operations){String operation=PcJson.text(store.data(task),"operation");if(operation.isBlank()||!Arrays.asList(operations).contains(operation)||store.mapper.list(PcTable.TOOL_CALL,task.getWorkspaceId(),task.getOwnerId(),task.getId(),"CONSUMED").stream().noneMatch(c->c.getKind().equals("control__"+operation)))throw PcException.deny("控制结果缺少固定用户操作及已消费许可");}
    private void snapshotResult(PcRecord task,Map<String,Object> payload){Map<String,Object> args=store.data(task).get("arguments") instanceof Map<?,?>?PcJson.object(store.data(task),"arguments"):Map.of();String operation=PcJson.text(store.data(task),"operation");if("CLEAN_PREVIEW".equals(payload.get("operation"))){requireControlResult(task,"SNAPSHOT_CLEAN_PREVIEW");new PcSnapshotClean(store).preview(task,payload);return;}if("CLEAN".equals(payload.get("operation"))){requireControlResult(task,"SNAPSHOT_CLEAN");new PcSnapshotClean(store).cleaned(task,payload);evidence.audit(task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),"SNAPSHOT_CLEAN","REPORTED",Map.of("range","current","backup",payload.get("backup")));return;}if(!args.containsKey("snapshotMetadataId")){metadata(PcTable.SNAPSHOT,task,payload,"SNAPSHOT");return;}requireControlResult(task,"SNAPSHOT_PREVIEW","SNAPSHOT_RESTORE");PcRecord snap=store.require(PcTable.SNAPSHOT,PcJson.number(args,"snapshotMetadataId"),true);if(!Objects.equals(snap.getWorkspaceId(),task.getWorkspaceId())||!Objects.equals(snap.getOwnerId(),task.getOwnerId())||!Objects.equals(snap.getSessionId(),task.getSessionId())||!Objects.equals(snap.getRunnerId(),task.getRunnerId())||!Objects.equals(Objects.toString(args.get("snapshotMetadataId"),""),Objects.toString(payload.get("snapshotMetadataId"),"")))throw PcException.deny("快照回执必须归属冻结会话、Runner及metadataId");String commit=PcJson.text(payload,"commitId");if(commit.isBlank())commit=PcJson.text(payload,"snapshotId");if(!Objects.equals(args.get("snapshotId"),commit))throw PcException.conflict("快照回执commit与冻结目标不同");Map<String,Object> data=store.data(snap);if(operation.equals("SNAPSHOT_PREVIEW")){Map<String,Object> preview=payload.get("restorePreview") instanceof Map<?,?>?PcJson.object(payload,"restorePreview"):PcJson.object(payload,"preview");validatePreview(preview,commit);for(String field:List.of("eventArtifactId","eventArtifactSha256","eventArtifactSize","eventArtifactContentUrl"))if(payload.containsKey(field))preview.put(field,payload.get(field));data.put("restorePreview",preview);data.put("previewTaskId",String.valueOf(task.getId()));data.put("previewCheckedAt",store.clock.instant().toString());}else{if(!Objects.equals(PcJson.text(args,"currentFingerprint"),PcJson.text(payload,"currentFingerprint")))throw PcException.conflict("恢复回执指纹没有绑定批准的文件状态");data.put("lastRestoredAt",store.clock.instant().toString());data.put("restoredByTaskId",String.valueOf(task.getId()));data.remove("restorePreview");}data.put("lastResult",payload);store.save(PcTable.SNAPSHOT,snap,data);}
    public static void validatePreview(Map<String,Object> preview,String commit){if(!PcJson.text(preview,"currentFingerprint").matches("[a-f0-9]{64}")||!(preview.get("canRestore") instanceof Boolean)||!(preview.get("files") instanceof List<?> files)||files.size()>10000||!(preview.get("conflicts") instanceof List<?> conflicts)||conflicts.size()>10000)throw PcException.invalid("预览需真实currentFingerprint、files、canRestore和conflicts证据");String target=PcJson.text(preview,"commitId");if(target.isBlank())target=PcJson.text(preview,"snapshotId");if(!target.isBlank()&&!target.equals(commit))throw PcException.conflict("预览commit不是冻结快照");Set<String> paths=new HashSet<>();for(Object item:files){if(!(item instanceof Map<?,?> file))throw PcException.invalid("预览文件须为对象");String path=PcPromptService.normalize(Objects.toString(file.get("path"),"")),status=Objects.toString(file.get("status"),"");if(!paths.add(path)||!Set.of("ADD","MODIFY","DELETE","UNCHANGED").contains(status))throw PcException.invalid("预览路径重复或状态非法");for(String field:List.of("currentHash","targetHash"))if(file.get(field)!=null&&!file.get(field).toString().matches("[a-f0-9]{64}"))throw PcException.invalid("预览文件哈希非法");if(!status.equals("ADD")&&file.get("currentHash")==null||!status.equals("DELETE")&&file.get("targetHash")==null)throw PcException.invalid("预览缺少当前或目标文件哈希");for(String field:List.of("currentMode","targetMode"))if(!file.containsKey(field)||file.get(field)!=null&&!(file.get(field) instanceof Number))throw PcException.invalid("预览六字段必须含实际文件模式");if(!status.equals("ADD")&&file.get("currentMode")==null||!status.equals("DELETE")&&file.get("targetMode")==null)throw PcException.invalid("预览缺少当前或目标文件模式");if(file.get("diff")!=null&&file.get("diff").toString().getBytes(java.nio.charset.StandardCharsets.UTF_8).length>65536)throw PcException.invalid("单文件diff超过64KiB，请下载完整预览产物");}if(Boolean.TRUE.equals(preview.get("canRestore"))&&!conflicts.isEmpty())throw PcException.conflict("存在冲突的预览不能标记canRestore");}
    private void summary(PcRecord task,Map<String,Object> payload){
        long before=PcJson.number(payload,"tokensBefore"),after=PcJson.number(payload,"tokensAfter");if(after>=before||after<0)throw PcException.invalid("压缩未降低Token，保留原历史");
        PcRecord session=store.require(PcTable.SESSION,task.getSessionId(),true);long start=PcJson.number(payload,"startSequence"),end=PcJson.number(payload,"endSequence");if(start<0||end<start||end>session.getSequenceNumber())throw PcException.invalid("压缩引用原消息范围非法");
        store.insert(PcTable.CONTEXT_SUMMARY,task.getWorkspaceId(),task.getOwnerId(),task.getSessionId(),task.getSessionId(),task.getRunnerId(),"SUMMARY","VERIFIED",null,payload);Map<String,Object> p=store.data(session);p.put("estimatedTokens",after);p.put("compressionCount",(p.get("compressionCount") instanceof Number n?n.intValue():0)+1);p.put("lastCompressionStatus","COMPLETED");store.save(PcTable.SESSION,session,p);
    }
    private void metadata(PcTable table,PcRecord task,Map<String,Object> payload,String kind){String hash=PcJson.text(payload,"sha256");if(hash.isBlank())hash=PcJson.text(payload,"manifestHash");if(!hash.matches("[a-f0-9]{64}"))throw PcException.invalid("产物/索引需SHA-256内容哈希");if("CANONICAL_MANIFEST".equals(payload.get("hashKind"))&&payload.get("eventArtifactId")==null){Map<String,Object> canonical=new LinkedHashMap<>(payload);canonical.remove("sha256");canonical.remove("manifestHash");if(!store.json.hash(canonical).equals(hash))throw PcException.conflict("派生元数据canonical哈希与内容不一致");}if(table==PcTable.ARTIFACT&&PcJson.number(payload,"size")>50L*1024*1024)throw new PcException(413,"PC_ARTIFACT_TOO_LARGE","产物超过50MB");Map<String,Object> record=new LinkedHashMap<>(payload);if(payload.get("eventArtifactId")!=null)record.put("hashVerification","ARTIFACT_REFERENCE_BOUND");else if("CANONICAL_MANIFEST".equals(payload.get("hashKind")))record.put("hashVerification","CENTER_CANONICAL_VERIFIED");PcRecord inserted=store.insert(table,task.getWorkspaceId(),task.getOwnerId(),task.getId(),task.getSessionId(),task.getRunnerId(),kind,"READY","task:"+task.getId()+":"+kind+":"+hash,record);if(table==PcTable.SNAPSHOT){inserted.setSequenceNumber(store.require(PcTable.SESSION,task.getSessionId(),false).getSequenceNumber()+1);store.save(table,inserted,record);}}
    private void connectionResult(PcRecord task,Map<String,Object> payload){Map<String,Object> original=payload;if(payload.containsKey("catalogueDigests")){payload=new LinkedHashMap<>(payload);payload.putAll(new PcCatalogueArtifact(store,artifacts).read(task,original));}String kind=PcJson.text(payload,"kind"),operation=PcJson.text(store.data(task),"operation");if(kind.equals("SKILL"))PcConnectionService.validateSkillSnapshot(store,task);Set<String> expected=switch(kind){case "PROVIDER"->Set.of("PROVIDER_REFRESH","PROVIDER_VERIFY");case "MCP"->Set.of("MCP_START","MCP_STOP","MCP_RESTART","MCP_READ_RESOURCE","MCP_READ_PROMPT");case "SKILL"->Set.of("SKILLS_RELOAD");case "BROWSER"->Set.of("BROWSER_PROBE","BROWSER_CONNECT","BROWSER_TABS","BROWSER_DISCONNECT");case "WECHAT"->Set.of("WECHAT_SETUP","WECHAT_START","WECHAT_STOP","WECHAT_PAUSE","WECHAT_RESUME","WECHAT_RESTART");default->Set.of();};if(!expected.contains(operation))throw PcException.deny("连接结果类型与冻结操作不符");Map<String,Object> frozen=PcJson.object(store.data(task),"arguments");if(frozen.containsKey("configId")&&!Objects.toString(frozen.get("configId"),"").equals(Objects.toString(payload.get("configId"),"")))throw PcException.deny("连接对象不等于冻结配置");if(frozen.containsKey("configVersion")&&!Objects.toString(frozen.get("configVersion"),"").equals(Objects.toString(payload.get("configVersion"),"")))throw PcException.conflict("连接结果不属于冻结配置定义版本");PcTable table=switch(kind){case "PROVIDER"->PcTable.PROVIDER_CONFIG;case "MCP"->PcTable.MCP_CONFIG;case "SKILL"->PcTable.SKILL_CONFIG;case "BROWSER"->PcTable.BROWSER_CONFIG;case "WECHAT"->PcTable.WECHAT_BINDING;default->throw PcException.invalid("连接结果类型非法");};if(kind.equals("SKILL")&&!payload.containsKey("configId")){Map<String,Object> args=PcJson.object(store.data(task),"arguments");Object configs=args.get("configs");if(!(configs instanceof List<?>)){configs=store.mapper.list(PcTable.SKILL_CONFIG,task.getWorkspaceId(),null,null,null).stream().map(store::view).toList();}for(Object value:(List<?>)configs)if(value instanceof Map<?,?> item){PcRecord skill=store.require(PcTable.SKILL_CONFIG,Long.parseLong(item.get("id").toString()),true);if(!Objects.equals(skill.getWorkspaceId(),task.getWorkspaceId()))throw PcException.deny("Skill不属于控制任务");Map<String,Object> data=store.data(skill);long definition=data.get("configurationVersion") instanceof Number n?n.longValue():skill.getVersion();if(definition!=Long.parseLong(item.get("version").toString()))throw PcException.conflict("Skill批准版本变化");data.put("configurationVersion",definition);data.put("effective",Boolean.TRUE.equals(data.get("enabled")));data.put("lastResult",payload);skill.setState(Boolean.TRUE.equals(data.get("enabled"))?"READY":"DISABLED");store.save(PcTable.SKILL_CONFIG,skill,data);}return;}PcRecord config=store.require(table,PcJson.number(payload,"configId"),true);if(!Objects.equals(config.getWorkspaceId(),task.getWorkspaceId()))throw PcException.deny("连接配置归属不符");Map<String,Object> p=store.data(config);long definition=p.get("configurationVersion") instanceof Number n?n.longValue():config.getVersion();if(definition!=PcJson.number(payload,"configVersion"))throw PcException.conflict("配置定义版本已改变");p.put("lastResult",original);p.putIfAbsent("configurationVersion",config.getVersion());for(String field:List.of("status","connected","tools","resources","prompts","catalogueDigests","logs","lastError","lastRefreshedAt","qrArtifactId","resourceContents","promptContents","effective","eventArtifactId","eventArtifactSha256","eventArtifactSize","eventArtifactContentUrl"))if(payload.containsKey(field))p.put(field,payload.get(field));if(kind.equals("MCP")&&payload.get("result") instanceof List<?> list&&PcJson.text(store.data(task),"operation").matches("MCP_(START|RESTART)"))p.put("tools",list);
        if(kind.equals("MCP")&&operation.matches("MCP_READ_(RESOURCE|PROMPT)")){String reference=PcJson.text(frozen,"reference"),field=operation.equals("MCP_READ_RESOURCE")?"resourceContents":"promptContents";Map<String,Object> cached=p.get(field) instanceof Map<?,?>?new LinkedHashMap<>(PcJson.object(p,field)):new LinkedHashMap<>();Object result=payload.get("result");if(result==null){if(payload.get("eventArtifactId")==null)throw PcException.invalid("MCP内容结果未上报");result=Map.of("artifactId",payload.get("eventArtifactId"),"sha256",payload.get("eventArtifactSha256"),"size",payload.get("eventArtifactSize"),"contentUrl",payload.get("eventArtifactContentUrl"),"offloaded",true);}cached.put(reference,result);p.put(field,cached);}
        if(kind.equals("PROVIDER")&&operation.equals("PROVIDER_VERIFY"))recordProviderVerification(task,config,payload);
        if(kind.equals("PROVIDER")&&payload.get("models") instanceof List<?> models){for(Object value:models){String model=value.toString();if(model.isBlank()||model.length()>256)throw PcException.invalid("供应商返回模型ID非法");boolean exists=store.mapper.list(PcTable.MODEL_CONFIG,task.getWorkspaceId(),null,null,null).stream().anyMatch(m->PcJson.number(store.data(m),"providerId")==config.getId()&&model.equals(PcJson.text(store.data(m),"modelId")));if(!exists)store.insert(PcTable.MODEL_CONFIG,task.getWorkspaceId(),task.getOwnerId(),config.getId(),null,null,"MODEL","CONFIGURED",null,Map.of("providerId",String.valueOf(config.getId()),"modelId",model,"contextWindow",128000,"supportsImages",false,"supportsThinking",false,"supportsTools",true,"capabilityKnown",false,"enabled",true));}}
        if(kind.equals("BROWSER")&&operation.equals("BROWSER_TABS")){Object result=payload.get("tabsResult");if(result==null)result=payload.get("tabs");if(result==null&&payload.get("eventArtifactId")==null)throw PcException.invalid("浏览器页签结果未上报");p.put("tabsResult",result==null?Map.of("artifactId",payload.get("eventArtifactId"),"contentUrl",payload.get("eventArtifactContentUrl")):result);Object reported=payload.get("tabs");if(reported==null)reported=payload.get("pages");if(reported==null&&result instanceof List<?>)reported=result;if(reported==null&&result instanceof Map<?,?> map){reported=map.get("pages");if(reported==null)reported=map.get("tabs");if(reported==null&&map.get("structuredContent") instanceof Map<?,?> structured){reported=structured.get("pages");if(reported==null)reported=structured.get("tabs");}}if(reported instanceof List<?> pages){p.put("tabs",browserPages(pages));p.put("tabsStatus","REPORTED");}else{p.remove("tabs");p.put("tabsStatus","UNREPORTED");}}else if(kind.equals("BROWSER")&&payload.get("result") instanceof Map<?,?> result)p.put("connected",Boolean.TRUE.equals(result.get("ok")));
        if(kind.equals("BROWSER")&&Set.of("BROWSER_CONNECT","BROWSER_DISCONNECT").contains(operation))browserCatalogue(task,frozen,payload,original);if(kind.equals("SKILL"))p.put("effective",true);if(payload.containsKey("status"))config.setState(PcJson.text(payload,"status"));else if(kind.equals("BROWSER"))config.setState(Boolean.TRUE.equals(p.get("connected"))?"CONNECTED":"ERROR");else if(kind.equals("PROVIDER"))config.setState("READY");store.save(table,config,p);}
    /** 浏览器实际重启的是已冻结Chrome MCP，同一次许可结果更新该正式目录而不修改配置定义。 */
    private void browserCatalogue(PcRecord task,Map<String,Object> frozen,Map<String,Object> payload,Map<String,Object> original){
        Map<String,Object> browser=PcJson.object(frozen,"config");PcRecord chrome=store.require(PcTable.MCP_CONFIG,PcJson.number(browser,"mcpConfigId"),true);Map<String,Object> data=store.data(chrome);long definition=data.get("configurationVersion") instanceof Number n?n.longValue():chrome.getVersion();
        if(!Objects.equals(chrome.getWorkspaceId(),task.getWorkspaceId())||!"chrome-devtools".equals(PcJson.text(data,"name"))||definition!=PcJson.number(browser,"mcpConfigVersion")||!Objects.equals(data.get("configHash"),browser.get("mcpConfigHash"))||!Objects.equals(data.get("configHash"),data.get("trustedHash")))throw PcException.conflict("浏览器Chrome MCP定义或批准hash已变化");
        if(!"READY".equals(payload.get("status"))||!(payload.get("tools") instanceof List<?>))return; // 未上报目录时不把旧目录改称本次已刷新。
        for(String field:List.of("tools","resources","prompts"))if(payload.containsKey(field)&&!(payload.get(field) instanceof List<?>))throw PcException.invalid("Chrome MCP目录必须是完整数组");
        data.put("configurationVersion",definition);for(String field:List.of("tools","resources","prompts","logs","catalogueDigests","eventArtifactId","eventArtifactSha256","eventArtifactSize","eventArtifactContentUrl"))if(payload.containsKey(field))data.put(field,payload.get(field));data.put("lastResult",original);data.put("browserTaskId",String.valueOf(task.getId()));data.put("lastRefreshedAt",store.clock.instant().toString());data.put("status","READY");chrome.setState("READY");store.save(PcTable.MCP_CONFIG,chrome,data);
    }
    private List<Map<String,Object>> browserPages(List<?> pages){if(pages.size()>10000)throw PcException.invalid("浏览器页签超过10000条，请下载完整结果");List<Map<String,Object>> result=new ArrayList<>();for(Object value:pages){if(!(value instanceof Map<?,?> page)||page.get("id")==null)throw PcException.invalid("浏览器页签须包含实际id");Map<String,Object> row=new LinkedHashMap<>();for(String field:List.of("id","title","url","type"))if(page.get(field)!=null){String text=page.get(field).toString();if(text.length()>(field.equals("id")?256:65536))throw PcException.invalid("浏览器页签字段过长");row.put(field,text);}result.add(row);}return result;}
    private void invalidateApprovals(PcRecord task){for(PcRecord a:store.mapper.list(PcTable.APPROVAL,task.getWorkspaceId(),null,task.getId(),null))if(Set.of("PENDING","APPROVED").contains(a.getState())){a.setState("EXPIRED");store.save(PcTable.APPROVAL,a,store.data(a));}}
    @Scheduled(fixedDelayString="${paicli.recovery-delay-milliseconds:15000}")
    @Transactional("paicliTransactionManager")
    public void recoverExpired(){for(PcRecord expired:store.mapper.expiredLeases(store.clock.instant(),100)){PcRecord task=store.require(PcTable.TASK,expired.getParentId(),true);PcRecord lease=store.require(PcTable.TASK_LEASE,expired.getId(),true);if(!lease.getState().equals("ACTIVE")||lease.getExpiresAt().isAfter(store.clock.instant()))continue;lease.setState("EXPIRED");store.save(PcTable.TASK_LEASE,lease,store.data(lease));if(!PcSessionService.terminal(task.getState())){task.setState("RECONCILE_REQUIRED");Map<String,Object> p=store.data(task);p.put("failureReason","租约失效，需核对已执行工具及外部副作用");store.save(PcTable.TASK,task,p);invalidateApprovals(task);evidence.event(store.require(PcTable.SESSION,task.getSessionId(),false),task.getId(),null,"TASK_RECONCILE_REQUIRED",Map.of("taskId",String.valueOf(task.getId())));}}}
    public static List<Map<String,Object>> steps(Map<String,Object> payload){Object raw=payload.get("steps");if(!(raw instanceof List<?> list)||list.isEmpty()||list.size()>100)throw new PcException(422,"PC_INVALID_DAG","计划应有1至100个步骤");List<Map<String,Object>> result=new ArrayList<>();for(Object o:list){if(!(o instanceof Map<?,?> m))throw PcException.invalid("步骤结构非法");Map<String,Object> step=new LinkedHashMap<>();m.forEach((k,v)->step.put(String.valueOf(k),v));step.putIfAbsent("status","PENDING");step.putIfAbsent("attempts",0);step.putIfAbsent("dependencies",List.of());result.add(step);}return result;}
    public static void validateDag(List<Map<String,Object>> steps){Map<String,List<String>> edges=new HashMap<>();for(var s:steps){String id=PcJson.text(s,"id");if(!id.matches("[A-Za-z0-9._:-]{1,128}")||edges.containsKey(id)||PcJson.text(s,"description").isBlank())throw new PcException(422,"PC_INVALID_DAG","计划ID重复/非法或描述为空");Object deps=s.get("dependencies");if(!(deps instanceof List<?>))throw PcException.invalid("dependencies须为数组");edges.put(id,((List<?>)deps).stream().map(String::valueOf).toList());}Set<String> done=new HashSet<>(),path=new HashSet<>();for(String id:edges.keySet())visit(id,edges,done,path);}
    private void recordProviderVerification(PcRecord task,PcRecord provider,Map<String,Object> payload){
        Map<String,Object> frozen=PcJson.object(store.data(task),"arguments"),proof=PcJson.object(payload,"verification");
        for(String field:List.of("modelId","modelVersion","secretVersion"))
            if(!Objects.toString(frozen.get(field),"").equals(Objects.toString(payload.get(field),"")))throw PcException.conflict("兼容验证回执版本不属于冻结对象");
        PcRecord model=store.require(PcTable.MODEL_CONFIG,PcJson.number(frozen,"modelId"),true);Map<String,Object> data=store.data(model),config=store.data(provider);
        if(!Objects.equals(model.getWorkspaceId(),task.getWorkspaceId())||PcJson.number(data,"providerId")!=provider.getId()
                ||model.getVersion()!=PcJson.number(frozen,"modelVersion")||!PcSub2ApiPolicy.applies(config)
                ||!PcJson.text(config,"wireApi").equals(PcJson.text(payload,"wireApi"))||!PcJson.text(data,"modelId").equals(PcJson.text(proof,"model")))
            throw PcException.conflict("兼容验证模型或协议已改变");
        for(String field:List.of("text","tools","stream","usage"))if(!Boolean.TRUE.equals(proof.get(field)))throw PcException.invalid("Sub2API兼容验证缺少必要能力");
        if(PcJson.number(proof,"calls")!=2)throw PcException.invalid("兼容验证调用次数不符合冻结范围");
        Map<String,Object> recorded=new LinkedHashMap<>(proof);recorded.put("wireApi",config.get("wireApi"));recorded.put("providerVersion",frozen.get("configVersion"));
        recorded.put("modelVersion",model.getVersion()+1);recorded.put("secretVersion",frozen.get("secretVersion"));recorded.put("taskId",String.valueOf(task.getId()));recorded.put("verifiedAt",store.clock.instant().toString());
        data.put("verification",recorded);data.put("capabilityKnown",true);data.put("supportsTools",true);model.setState("READY");store.save(PcTable.MODEL_CONFIG,model,data);
    }
    private static void visit(String id,Map<String,List<String>> edges,Set<String> done,Set<String> path){if(done.contains(id))return;if(!edges.containsKey(id)||!path.add(id))throw new PcException(422,"PC_INVALID_DAG","计划依赖不存在或存在环");for(String dep:edges.get(id))visit(dep,edges,done,path);path.remove(id);done.add(id);}
}
